function convertSearchName(name) {
	return name.replace(/[ '"-.]/g, '').normalize("NFD").replace(/\p{Diacritic}/gu, "").toLowerCase();
}

function binarySearch(elem, arr, prop) {
    let m = 0;
    let n = arr.length - 1;
    while (m <= n) {
        let k = (n + m) >> 1;
        if (elem > arr[k][prop]) {
            m = k + 1;
        }
		else if(elem < arr[k][prop]) {
            n = k - 1;
        }
		else {
            return k;
        }
    }
    return ~m;
}

function sortByProperty(a, b, property) {
	let valueA = property.split('.').reduce((o, i) => o[i], a);
	let valueB = property.split('.').reduce((o, i) => o[i], b);
	if (valueA < valueB){
		return -1;
	}
	if (valueA > valueB){
		return 1;
	}
	return 0;
}
